@app.route("/api/threats")
def api_threats():
    conn = get_connection()
    try:
        rows = [dict(r) for r in conn.execute("SELECT * FROM threats ORDER BY score DESC LIMIT 500").fetchall()]
        return jsonify({"threats": rows, "total": len(rows)})
    finally:
        conn.close()

