@app.route("/api/graph")
def api_graph():
    conn = get_connection()
    try:
        edges = [dict(r) for r in conn.execute(
            "SELECT * FROM kg_edges ORDER BY weight DESC LIMIT 300"
        ).fetchall()]
        node_set = {}
        for e in edges:
            for p in ("source", "target"):
                key = f"{e[p+'_type']}:{e[p+'_id']}"
                if key not in node_set:
                    node_set[key] = {"id": key, "type": e[p+"_type"], "label": e[p+"_id"][:12]}
        return jsonify({"nodes": list(node_set.values()),
                        "links": [{"source": f"{e['source_type']}:{e['source_id']}",
                                    "target": f"{e['target_type']}:{e['target_id']}",
                                    "relation": e["relation"], "weight": e["weight"]} for e in edges]})
    finally:
        conn.close()

@app.route("/api/stats")
def api_stats():
    conn = get_connection()
    try:
        stats = {}
        for tbl in ["threats", "vulnerabilitys", "assets", "indicators", "campaigns", "actors", "kg_edges"]:
            try:
                stats[tbl] = conn.execute(f"SELECT COUNT(*) c FROM {tbl}").fetchone()["c"]
            except Exception:
                stats[tbl] = 0
        return jsonify(stats)
    finally:
        conn.close()

